// AI behavioral-divergence report.
//
// Turns the 96 archived human games (logs/*.json) into an "expert profile" and
// compares it against an "AI profile" generated by running fresh AI-vs-AI games
// through the CURRENT heuristic AI (src/play/randomAI.ts). Both corpora carry a
// turnLog in the identical {turn, kind, side, payload} shape, so a single metric
// extractor runs over both. The diff is ranked by magnitude, surfacing the
// decisions where the AI most disagrees with a player who wins ~every game.
//
// IMPORTANT framing (see CLAUDE.md "AI logs & analysis"): every human log is an
// EXPERT WIN — the user plays BOTH sides and basically never loses to the AI.
// So this is imitation-gap analysis ("play more like the expert"), not
// outcome-learning. The output is a prioritized heuristic backlog, not a model.
//
// Usage:
//   node scripts/ai-divergence.mjs [aiGames=24] [maxRounds=14]
//
// Notes:
//  - Human side: in a human log BOTH sides are the expert (user plays both), so
//    every Empire decision feeds the expert-Empire profile and every Rebel
//    decision the expert-Rebel profile.
//  - AI side: fresh games are generated in-process so the profile reflects the
//    AI as it stands RIGHT NOW (post #190 fix), not a stale tournament run.

import { readFileSync, readdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readGameLog } from './lib/log-reader.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..');

const AI_GAMES = Number(process.argv[2] ?? 24);
const MAX_ROUNDS = Number(process.argv[3] ?? 14);

// ---- tsx so we can import the .ts engine + AI ----
try {
  const mod = await import('tsx/esm/api');
  if (mod?.register) mod.register();
} catch {
  // tsx not present as api — fall back to loader already registered by runner
}
const { createGame } = await import('../src/engine/setup.ts');
const phases = await import('../src/engine/phases.ts');
const { stepOnce: aiStep, seedAI } = await import('../src/play/randomAI.ts');

// ---------------------------------------------------------------------------
// Metric extraction — runs over a turnLog (array of {turn, kind, side, payload}).
// Produces a per-side bag of counters plus a couple of game-level facts.
// Everything is later normalized PER ROUND (rounds = max turn) so the expert's
// shorter games and the AI's longer ones are comparable.
// ---------------------------------------------------------------------------

// Command-phase action kinds we care about for the pass/act ratio (the #190
// class of bug: AI burning command opportunities on pass).
const COMMAND_ACT = new Set(['reveal-mission', 'activate-system']);

function extractMetrics(turnLog) {
  const sides = ['Empire', 'Rebel'];
  const m = {
    rounds: 0,
    perSide: Object.fromEntries(sides.map((s) => [s, {
      // raw kind counts (we keep the full bag; report picks the interesting ones)
      kinds: {},
      // build-queue composition: typeId -> count
      built: {},
      // deploy composition
      deployed: {},
    }])),
  };
  for (const e of turnLog) {
    if (typeof e.turn === 'number' && e.turn > m.rounds) m.rounds = e.turn;
    // A few strategically important kinds are logged without a `side` because
    // they can only ever belong to one faction. Attribute them explicitly.
    let side = e.side;
    if (!side && (e.kind === 'subjugated' || e.kind === 'liberated')) side = 'Empire';
    if (!side || !m.perSide[side]) continue;
    const ps = m.perSide[side];
    ps.kinds[e.kind] = (ps.kinds[e.kind] ?? 0) + 1;
    if (e.kind === 'build-queue' && e.payload) {
      const t = e.payload.typeId ?? e.payload.unitType ?? e.payload.type;
      if (t) ps.built[t] = (ps.built[t] ?? 0) + 1;
    }
    if (e.kind === 'deploy' && e.payload) {
      const t = e.payload.typeId ?? e.payload.unitType ?? e.payload.type;
      if (t) ps.deployed[t] = (ps.deployed[t] ?? 0) + 1;
    }
  }
  return m;
}

// Derive the comparable, normalized metrics for one side from a list of games'
// raw metric bags. Returns { metricName -> {mean, n} } where mean is per-round.
function profileSide(games, side) {
  const acc = {};   // metricName -> array of per-game values
  const push = (name, v) => { (acc[name] ??= []).push(v); };

  for (const g of games) {
    const ps = g.perSide[side];
    const rounds = Math.max(1, g.rounds);
    const k = ps.kinds;
    const get = (kind) => k[kind] ?? 0;

    // --- command economy: the headline #190 metric ---
    const reveal = get('reveal-mission');
    const activate = get('activate-system');
    const pass = get('pass');
    const commandTotal = reveal + activate + pass;
    push('command/pass-share', commandTotal ? pass / commandTotal : 0);
    push('command/reveal-per-round', reveal / rounds);
    push('command/activate-per-round', activate / rounds);
    push('command/pass-per-round', pass / rounds);

    // --- leader usage ---
    const assign = get('assign-leader');
    const skip = get('skip-assignment');
    push('assignment/skip-share', (assign + skip) ? skip / (assign + skip) : 0);
    push('assignment/assign-per-round', assign / rounds);

    // --- missions ---
    push('mission/unopposed-per-round', get('mission-unopposed') / rounds);
    push('mission/roll-per-round', get('mission-roll') / rounds);
    push('mission/draw-per-round', get('draw-mission') / rounds);
    push('mission/return-to-hand-per-round', get('mission-return-to-hand') / rounds);
    push('mission/discard-per-round', get('mission-discard') / rounds);

    // --- production / forces ---
    push('build/build-queue-per-round', get('build-queue') / rounds);
    push('build/deploy-per-round', get('deploy') / rounds);
    push('build/recruit-per-round', get('recruit-leader') / rounds);

    // --- maneuver ---
    push('maneuver/move-unit-per-round', get('move-unit') / rounds);
    push('maneuver/place-leader-per-round', get('place-leader') / rounds);

    // --- combat ---
    push('combat/attack-per-round', get('combat-attack') / rounds);
    push('combat/tactic-per-round', get('combat-tactic') / rounds);
    push('combat/retreat-per-round', get('combat-retreat') / rounds);

    // --- territory (Empire-relevant but tracked for both) ---
    push('territory/subjugated-per-round', get('subjugated') / rounds);

    // --- ECONOMY: loyalty growth drives production. Build slots are 1:1 with
    // loyal resource icons (engine refreshBuildIfApplicable), so a Rebel that
    // flips fewer systems builds fewer units — the suspected root of the
    // build/deploy/move cascade. gain-loyalty is side-tagged; loyalty-already
    // is a WASTED loyalty mission (ran on an already-loyal system). ---
    push('econ/gain-loyalty-per-round', get('gain-loyalty') / rounds);
    push('econ/loyalty-wasted-per-round', get('loyalty-already') / rounds);

    // --- game shape ---
    push('shape/rounds', g.rounds);
  }

  const out = {};
  for (const [name, arr] of Object.entries(acc)) {
    const n = arr.length;
    const mean = n ? arr.reduce((a, b) => a + b, 0) / n : 0;
    out[name] = { mean, n };
  }
  return out;
}

// ---------------------------------------------------------------------------
// Load expert corpus
// ---------------------------------------------------------------------------
function loadHumanGames() {
  const dir = join(ROOT, 'logs');
  const files = readdirSync(dir).filter((f) => f.endsWith('.json'));
  const games = [];
  for (const f of files) {
    // Dual-format via the shared reader — v2 logs (post-2026-07-10) would
    // otherwise be silently skipped and the expert corpus would stop growing.
    let events;
    try { events = readGameLog(join(dir, f)).events; } catch { continue; }
    if (!Array.isArray(events) || events.length === 0) continue;
    games.push(extractMetrics(events));
  }
  return games;
}

// ---------------------------------------------------------------------------
// Generate AI corpus (fresh self-play through the current AI)
// ---------------------------------------------------------------------------
function runOneAIGame(data, seed) {
  seedAI(seed);
  const G = createGame(data, { seed, autoSetupUnits: false });
  let safety = 0;
  while (G.phase === 'Setup' && safety < 200) {
    safety++;
    const did = aiStep(G, G.currentPlayer);
    if (!did) {
      const other = G.currentPlayer === 'Rebel' ? 'Empire' : 'Rebel';
      const did2 = aiStep(G, other);
      if (!did2) {
        const r1 = phases.setupAutoFill(G, 'Rebel');
        const r2 = phases.setupAutoFill(G, 'Empire');
        if (!r1.ok && !r2.ok) break;
      }
    }
  }
  let steps = 0;
  const STEP_CAP = 200000;
  while (!G.isGameOver && steps < STEP_CAP) {
    const side = G.currentPlayer;
    if (aiStep(G, side)) { steps++; continue; }
    const other = side === 'Rebel' ? 'Empire' : 'Rebel';
    if (aiStep(G, other)) { steps++; continue; }
    break;
  }
  if (!G.isGameOver && G.timeMarker > MAX_ROUNDS) {
    G.isGameOver = true; G.winReason = 'max-rounds-reached';
  }
  return { metrics: extractMetrics(G.turnLog), winner: G.winner ?? 'stuck', steps, rounds: G.timeMarker };
}

function loadDataCatalog() {
  // Mirror tournament.mjs exactly: load the tracked source catalog from assets/.
  const read = (n) => JSON.parse(readFileSync(join(ROOT, 'assets', n), 'utf8'));
  return {
    systems: read('systems.json'),
    adjacency: read('adjacency.json'),
    leaders: read('leaders.json'),
    actions: read('actions.json'),
    missions: read('missions.json'),
    objectives: read('objectives.json'),
    tactics: read('tactics.json'),
    probes: read('probes.json'),
  };
}

// ---------------------------------------------------------------------------
// Report
// ---------------------------------------------------------------------------
function fmt(n) { return Number.isFinite(n) ? n.toFixed(2) : String(n); }

function diffReport(expert, ai, side) {
  const names = Object.keys(expert).filter((k) => k !== 'shape/rounds' || true);
  const rows = [];
  for (const name of names) {
    const e = expert[name]?.mean ?? 0;
    const a = ai[name]?.mean ?? 0;
    const absGap = Math.abs(e - a);
    // relative gap vs the larger of the two (avoid div-by-zero); used for ranking
    const denom = Math.max(Math.abs(e), Math.abs(a), 1e-9);
    const relGap = absGap / denom;
    rows.push({ name, expert: e, ai: a, absGap, relGap });
  }
  // Rank by relative gap, but require the absolute gap to be non-trivial so we
  // don't surface "expert 0.01 vs AI 0.00" as a top finding.
  rows.sort((x, y) => (y.relGap * Math.min(1, y.absGap * 4)) - (x.relGap * Math.min(1, x.absGap * 4)));
  console.log(`\n${'='.repeat(72)}\n  ${side.toUpperCase()} — expert vs current AI (per-round means)\n${'='.repeat(72)}`);
  console.log('  ' + 'metric'.padEnd(38) + 'expert'.padStart(9) + 'AI'.padStart(9) + '  gap   dir');
  console.log('  ' + '-'.repeat(66));
  for (const r of rows) {
    const dir = r.ai > r.expert ? 'AI↑' : r.ai < r.expert ? 'AI↓' : '=';
    const flag = r.relGap >= 0.5 && r.absGap >= 0.15 ? ' «' : '';
    console.log('  ' + r.name.padEnd(38) + fmt(r.expert).padStart(9) + fmt(r.ai).padStart(9)
      + '  ' + (r.relGap * 100).toFixed(0).padStart(3) + '%  ' + dir + flag);
  }
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
console.log('Loading expert corpus (logs/*.json)...');
const humanGames = loadHumanGames();
console.log(`  ${humanGames.length} expert games loaded.`);

console.log(`Generating ${AI_GAMES} AI self-play games (current randomAI, maxRounds=${MAX_ROUNDS})...`);
const data = loadDataCatalog();
const aiGames = [];
const aiWinners = {};
for (let i = 0; i < AI_GAMES; i++) {
  const seed = 1000 + i * 7;
  let r;
  try { r = runOneAIGame(data, seed); }
  catch (err) { console.log(`  game ${i} (seed ${seed}) errored: ${err.message}`); continue; }
  aiGames.push(r.metrics);
  aiWinners[r.winner] = (aiWinners[r.winner] ?? 0) + 1;
  process.stdout.write(`\r  ${aiGames.length}/${AI_GAMES} done`);
}
console.log(`\n  AI self-play winners:`, aiWinners);

for (const side of ['Empire', 'Rebel']) {
  const expert = profileSide(humanGames, side);
  const ai = profileSide(aiGames, side);
  diffReport(expert, ai, side);
}

console.log('\n  «  = high-divergence flag (rel gap ≥50% and abs gap ≥0.15/round)');
console.log('  Read AI↑ = AI does this MORE than the expert; AI↓ = LESS.\n');
